const lessonNotes = {
  'Alfabe ve temel telaffuz': 'Harf adları ile harflerin kelime içindeki seslerini ayır. İngilizcede aynı harf farklı kelimelerde farklı ses verebilir; dinle, tekrar et ve örnek kelimelerle eşleştir.',
  'Selamlaşma ve vedalaşma': 'Resmî ve samimi selamlaşmaları bağlama göre seç. Good morning günün erken saatlerinde, Hello ise daha genel durumlarda kullanılabilir.',
  'Kendini tanıtma': 'Ad, yaş, şehir, meslek ve ilgi alanlarını kısa cümlelerle anlat. Cevapları ezberlemek yerine kendi bilgilerinle yeniden kur.',
  'Kişi zamirleri': 'I, you, he, she, it, we ve they özne görevindedir. İngilizcede özne çoğu cümlede açıkça belirtilir.',
  'Present Perfect': 'Have/has + past participle (V3) yapısını kullan. Deneyim, henüz bitmemiş zaman dilimleri ve sonucu şimdi görülen olaylara odaklan.',
  'Third Conditional': 'If + past perfect, would have + V3 kalıbı geçmişte farklı gerçekleşmiş olabilecek bir sonucu düşünmek için kullanılır.',
  'Cleft Sentences': 'It-cleft ve wh-cleft yapıları cümlenin belirli bir bölümünü öne çıkarır. Vurgu değiştiğinde dinleyicinin dikkatinin yönü de değişir.',
  'Critical Reading': 'Metnin iddiasını, kanıt türünü, varsayımlarını ve karşı görüşleri ayır. Bir iddianın güçlü görünmesi onun kanıtlandığı anlamına gelmez.'
};

const levelMeta = Object.fromEntries(levelData.map(level => [level.id, level]));
const allLessons = [];
levelData.forEach((level, levelIndex) => {
  level.modules.forEach((module, moduleIndex) => {
    module.lessons.forEach((title, lessonIndex) => {
      const id = `${level.id}-${moduleIndex + 1}-${lessonIndex + 1}`;
      const examples = module.examples.map((example, i) => ({ en: example[0], tr: example[1], index: i + 1 }));
      allLessons.push({
        id, level: level.id, levelIndex, moduleIndex, lessonIndex,
        moduleTitle: module.title, moduleSubtitle: module.subtitle, title,
        focus: module.focus, rule: module.rule,
        objective: `Bu dersin sonunda “${title}” konusunu günlük ve anlamlı cümlelerde doğru biçimde kullanabileceksin.`,
        explanation: lessonNotes[title] || `${title} konusunu ${module.focus.toLocaleLowerCase('tr-TR')} bağlamında ele al. Önce yapının ne zaman ve neden kullanıldığını kavra; ardından olumlu, olumsuz ve soru örneklerini karşılaştır. Cümleyi yalnızca kurala göre değil, konuşmanın amacına göre seçmeye çalış.`,
        commonMistake: level.id === 'A1' ? 'Türkçedeki kelime sırasını birebir taşımak ve yardımcı fiili unutmak.' : level.id === 'A2' ? 'Zaman ifadesini dikkate almadan uygun olmayan zamanı seçmek.' : level.id === 'B1' ? 'Birbirine benzeyen zamanları veya bağlaçları anlam farkını gözetmeden kullanmak.' : level.id === 'B2' ? 'Karmaşık yapıyı doğru kurarken anlamın ve zaman ilişkisinin tutarlılığını kaçırmak.' : 'Üslup ve kesinlik derecesini bağlama göre ayarlamadan aşırı iddialı ifade kullanmak.',
        examples, questions: module.questions,
        vocabulary: module.examples.slice(0, 5).map((e, i) => ({ word: e[0].split(' ').filter(Boolean).slice(0, 2).join(' '), meaning: e[1], pronunciation: 'Dinle ve tekrar et', example: e[0] }))
      });
    });
  });
});

export const curriculum = levelData;
export const lessons = allLessons;
export const getLesson = id => allLessons.find(item => item.id === id);
export const getLevel = id => levelMeta[id] || levelData[0];
export const levelOrder = levelData.map(level => level.id);
export const lessonCount = allLessons.length;
